set -euo pipefail
upload_dir=$(getent passwd "$SUDO_USER" | cut -d: -f6)
cd /opt/news-flow/current
runuser -u news-flow -- /opt/news-flow/node/bin/node --input-type=module - <<'NODE'
import fs from 'node:fs';import {gzipSync} from 'node:zlib';import {createHash} from 'node:crypto';import {loadNewsRegistry} from './src/newsFlow/registry.mjs';import {NewsHttpDriver,NewsProxyPool} from './src/newsFlow/transport.mjs';import {NewsNetworkPool} from './src/newsFlow/networkPool.mjs';const root='/var/lib/news-flow/qc-alt25-20261122',registry=await loadNewsRegistry(),pool=await NewsProxyPool.load('/etc/news-flow/proxies.json',{rotation:'request'}),network=new NewsNetworkPool({workers:1}),driver=new NewsHttpDriver({state:{cacheResponses:false,failedUrl:()=>false,request:()=>null,reserve:()=>true,cache:()=>null,completeHttpResponse:()=>{}},network,pool,allowedDomains:[...registry.allowedDomains,'data-api.coindesk.com'],siteCooldown:false,maxWireRequests:5}),r={at:new Date().toISOString(),docs:'https://developers.coindesk.com/documentation/data-api/news_v1_article_list',checks:[]};
async function get(url){const p=await driver.get('qc-alt25-cd-api',url,registry.sources.get('coindesk.com').config,[],{reviewFailed:true,taskRole:'publisher_dependency'}),o={url,error:p.error,statusCode:p.statusCode};let data;if(p.html){o.file=root+'/evidence/'+createHash('sha256').update(p.html).digest('hex')+'.gz';fs.writeFileSync(o.file,gzipSync(p.html));try{data=JSON.parse(p.html);o.keys=Object.keys(data);o.errorCode=data.Err?.type||data.Err?.message;if(Array.isArray(data.Data)){o.coinDeskSources=data.Data.filter(s=>/coindesk/i.test(s.NAME||s.SOURCE_NAME||'')).map(s=>({ID:s.ID,NAME:s.NAME,URL:s.URL}));o.articles=data.Data.filter(s=>s.TITLE).map(a=>({id:a.ID,url:a.URL,title:a.TITLE,publishedOn:a.PUBLISHED_ON,bodyChars:a.BODY?.length,subtitle:a.SUBTITLE,bodyPreview:a.BODY?.slice(0,160)}));}}catch{}}r.checks.push(o);console.log(JSON.stringify(o));return {p,data};}
try{const sources=await get('https://data-api.coindesk.com/news/v1/source/list?lang=EN');if(!sources.p.error){const id=sources.data?.Data?.find(s=>/^coindesk$/i.test(s.NAME||''))?.ID;if(id)await get('https://data-api.coindesk.com/news/v1/article/list?lang=EN&source_ids='+id+'&limit=5');}r.finishedAt=new Date().toISOString();fs.writeFileSync(root+'/coindesk-api.json',JSON.stringify(r,null,2));}finally{await network.close();}
NODE
install -o "$SUDO_USER" -m 0600 /var/lib/news-flow/qc-alt25-20261122/coindesk-api.json "$upload_dir/.qc-alt25-coindesk-api.json"
